expected['local_review_progress']={'covered':a['covered_paths_in_main_published_and_unpublished_local_review_commits_after'],'remaining':a['remaining_after_local_batch'],'published_batches':len(published),'pending_local_batches':len(pending),'next_path':a['next_path'],'counts_include_unpublished_local_commits':True,'latest_batch_completion_counts':a['completion_counts'],'coverage_definition':a['coverage_definition']}
expected['next_original_queue_index']=max(before.get('next_original_queue_index',0),expected['local_review_progress']['covered']-1)
expected['next_batch']='Continue authorized local review batch306 from fresh origin/main. Select from the union of validated main, published branches and committed unpublished local batches, keeping their states explicit. Publication remains pending direct approval; do not retry rejected publication or fabricate published coverage.'
expected['next_sources']={'record':a['next_path'],'support_note':'No next-batch judgment yet. Fresh inspect, target/owner/ancestor reading and source QA remain mandatory. Pending local reviews count for selection only, not published/main coverage.'}
