proof={'actor':'/root','status':'clear','at':now(),'before':pin(B/'continue-before-local-checkpoint.json'),'after':pin(B/'continue-after-local-checkpoint.json'),'checkpoint':pin(B/'checkpoint.json'),'changed_keys':changed,'scope':'Independent full expected continuation object and exact serialized bytes reconstruct attained local updates; historical keys preserved. All20 committed/live/archive bytes checked through actual ROOT Git observations.','git_observation':op,'archive':pin(B/'saved-bundle-copies.json'),'publication_hold':True}
pp=write('root-checkpoint305-continuation-proof.json',proof)
att={'status':'attained_inputs_only','publication_hold':True,'historical_pin_resolutions':[],'observation':op}
for k,n in [('commit','root-commit305-execution.json'),('postcommit','root-postcommit305-execution.json'),('checkpoint','root-checkpoint305-execution.json'),('copy','root-copy305-execution.json'),('final_native','root-finalchecks305-execution.json')]:
 assert read(B/n)['exit_code']==0;att[k]=pin(B/n)
ap=write('root-closure305-attained-inputs.json',att)
